final readonly class CacheQueryMiddleware implements MiddlewareInterface
{
    public function __construct(private CacheInterface $cache) {}
    public function handle(Envelope $envelope, StackInterface $stack): Envelope
    {
        $query = $envelope->getMessage();
        if (!$query instanceof CacheableQuery) { return $stack->next()->handle($envelope, $stack); }
        $result = $this->cache->get(CacheKeys::forQuery($query), function (ItemInterface $item) use ($envelope, $stack) {
            $item->expiresAfter(CacheTtl::Query->value);
            return $stack->next()->handle($envelope, $stack)->last(HandledStamp::class)?->getResult();
        });
        return $envelope->with(new HandledStamp($result, self::class));
    }
}
// messenger.yaml: query.bus middleware: [Framework\Bus\CacheQueryMiddleware]

